// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testFuzz_property(uint256 v, uint8 n) public {
        vm.assume(n > 0 && n <= 8);
        address[] memory tos = new address[](n);
        Reverter reverter = new Reverter();
        for (uint i = 0; i < n - 1; i++) {
            tos[i] = address(this);
        }
        tos[n - 1] = address(reverter);
        bool ok;
        try c.transfer(address(this), address(reverter), tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Expected revert but call succeeded");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
